            e.dxf.end = (265, 0, 0)
        elif near(s, (276, 42)) and near(t, (273, 45)):
            msp.delete_entity(e)
        elif near(s, (273, 45)) and near(t, (3, 45)):
            e.dxf.start = (272, 45, 0)
    elif e.dxftype() == 'ARC':
        if abs(e.dxf.radius - 10) < 1e-6:
            e.dxf.center = (265, 10, 0)

attribs = {'layer': proto.dxf.layer, 'color': proto.dxf.color}
for a, b in [((276, 42), (275, 42)), ((275, 42), (272, 45)), ((276, 10), (275, 10))]:
    msp.add_line(a + (0,), b + (0,), dxfattribs=attribs)
d.audit()
d.saveas(p)
for e in msp:
    if e.dxftype() == 'LINE':
        print('LINE', e.dxf.start.xyz, e.dxf.end.xyz)
    else:
        print(e.dxftype(), e.dxf.center.xyz, e.dxf.radius, e.dxf.start_angle, e.dxf.end_angle)

